
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_regtpss_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_regtpss", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.786413111101194e+00, -4.689499001922675e+00, -4.553619526993147e+00, -4.365228188197128e+00, -4.108184350179475e+00, -3.765413846773622e+00, -3.323061038397007e+00, -2.778707714824631e+00, -2.156190640924494e+00, -1.528386258276708e+00, -9.962946988814587e-01, -6.873212224181257e-01, -6.006427372992664e-01, -5.097843587534727e-01, -3.616776719708210e-01, -2.228705630091923e-01, -1.252046012738720e-01, -4.901720192767779e-02, -1.080650830572228e-02, -1.216194253504090e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


